"use client";

import Link from "next/link";
import React, { useState, useEffect } from "react";
import { FaBars, FaTimes, FaUsers, FaShareAlt, FaLaptop, FaVideo, FaClock, FaTasks, FaCalendarAlt, FaGraduationCap, FaBook, FaComments } from "react-icons/fa";

export default function HomePage() {
  const [isOpen, setIsOpen] = useState(false);
  
  // Ensure isOpen state is initialized properly only on the client side
  useEffect(() => {
    setIsOpen(false);  // Reset to false on client side to avoid hydration mismatch
  }, []);

  return (
    <div className="bg-gray-100 min-h-screen">
      {/* Navbar */}
      <nav className="bg-blue-900 text-white py-4 px-6 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          {/* Logo */}
          <div className="flex items-center space-x-3">
            <img src="/images/logo.png" alt="Brain Wave Logo" className="h-10 w-auto" />
            <span className="text-xl font-bold">Brain Wave</span>
          </div>

          {/* Desktop Nav Links & Buttons */}
          <div className="hidden md:flex items-center space-x-6">
            {["About Us", "Coworking", "University", "Contact", "Help"].map((item) => (
              <a key={item} href="/coworking/page.tsx" className="hover:text-gray-300 transition duration-300">
                {item}
              </a>
            ))}

            {/* Login & Register Buttons */}
            <Link href="/auth/signin">
              <button className="px-4 py-2 bg-white text-blue-900 font-bold rounded-md hover:bg-gray-200 transition duration-300">
                Login
              </button>
            </Link>

            <Link href="/auth/signup">
              <button className="px-4 py-2 bg-blue-700 text-white font-bold rounded-md hover:bg-blue-950 transition duration-300">
                Register
              </button>
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden focus:outline-none text-2xl"
            aria-label="Toggle menu"
          >
            {isOpen ? <FaTimes /> : <FaBars />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isOpen && (
          <div className="md:hidden flex flex-col items-center space-y-4 bg-blue-800 py-6">
            {["About Us", "Coworking", "University", "Contact", "Help"].map((item) => (
              <a key={item} href="/coworking/page.tsx" className="hover:text-gray-300 transition duration-300">
                {item}
              </a>
            ))}

            {/* Mobile Login & Register Buttons */}
            <Link href="/auth/signIn">
              <button className="px-4 py-2 bg-white text-blue-900 font-bold rounded-md hover:bg-gray-200 transition duration-300">
                Login
              </button>
            </Link>

            <Link href="/auth/signup">
              <button className="px-4 py-2 bg-blue-700 text-white font-bold rounded-md hover:bg-blue-950 transition duration-300">
                Register
              </button>
            </Link>
          </div>
        )}
      </nav>

      {/* Hero Section */}
      <header className="relative flex items-center bg-blue-900 text-white px-10 py-20 overflow-hidden">
        <div className="flex flex-col gap-5 container w-auto">
          <h1 className="text-4xl font-bold">
            Let's Make Your Life Better Together
          </h1>
          <h3 className="text-xl ">Enhance your academic and professional journey with a smart platform designed for seamless collaboration and growth.</h3>
        </div>
        <div><img src="/images/coworking.png" alt="Brain Wave Logo" className="h-72 w-auto" />
        </div>
      </header>

      {/* Features Section */}
      <div className="grid place-items-center h-full w-full">
        <button className="text-2xl pt-10 font-bold text-black ">
          How can we help you?
        </button>
      </div>
      <section className="container mx-auto py-16 px-6 grid grid-cols-1 md:grid-cols-3 gap-8">
        {[ 
          { icon: <FaUsers />, title: "Collaborative Workspaces", description: "Create virtual rooms for real-time collaboration with teammates." },
          { icon: <FaShareAlt />, title: "One-Click Sharing", description: "Instantly share rooms with colleagues via a simple link." },
          { icon: <FaVideo />, title: "Live Meetings", description: "Host virtual study sessions." },
          
          { icon: <FaClock />, title: "Time Management", description: "Plan your studies effectively." },
          { icon: <FaTasks />, title: "Task Management", description: "Create, organize, and complete tasks with satisfaction."},
          { icon: <FaCalendarAlt />, title: "Calendar Integration", description: "Seamlessly integrate with your existing calendar apps." },
          
          { icon: <FaUsers />, title: "Alumni Network", description: "Connect with graduates and build professional relationships." },
          { icon: <FaGraduationCap />, title: "Course Library", description: "Access shared lectures, tutorials, and educational content." },
          { icon: <FaBook />, title: "Discussion Forums", description: "Engage in meaningful conversations with your community." }
        ].map(({ icon, title, description }) => (
          <div key={title} className="bg-white p-6 rounded-lg shadow-md text-center transition-transform duration-300 ease-in-out transform hover:scale-105 hover:shadow-lg">
            <div className="flex justify-center items-center text-blue-900 text-4xl mb-4">{icon}</div>
            <h3 className="text-xl text-black font-bold mb-2">{title}</h3>
            <p className="text-gray-600">{description}</p>
          </div>
        ))}
      </section>

      {/* Contact Section */}
      <div className="container px-4 mx-auto pb-10">
        <div className="mx-auto">
          <div className="max-w-md mx-auto px-8 py-6 bg-white rounded-lg shadow-lg focus:outline-none hover:ring-2 hover:ring-blue-900 transition duration-300">
            <h2 className="text-2xl font-semibold text-gray-800 mb-4">Contact Us</h2>
            <form>
              <div className="mb-4">
                <label className="block text-gray-800 mb-1" htmlFor="name">Your Name</label>
                <input
                  className="w-full px-4 py-2 bg-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-900 transition duration-300"
                  placeholder="Enter your name"
                  type="text"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-800 mb-1" htmlFor="email">Your Email</label>
                <input
                  className="w-full px-4 py-2 bg-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-900 transition duration-300"
                  placeholder="Enter your email"
                  name="email"
                  id="email"
                  type="email"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-800 mb-1" htmlFor="message">Your Message</label>
                <textarea
                  className="w-full px-4 py-2 bg-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-900 transition duration-300"
                  rows={4}
                  placeholder="Enter your message"
                  name="message"
                  id="message"
                ></textarea>
              </div>
              <button
                className="w-full bg-blue-800 text-gray-100 py-2 px-4 rounded-lg hover:bg-blue-950 transition duration-300"
                type="submit"
              >
                Send Message
              </button>
            </form>
          </div>
        </div>
      </div>

      {/* Footer */}
      <footer className="bg-blue-900 text-white text-center py-8">
        <p>&copy; 2025 BrainWave. All rights reserved.</p>
      </footer>

      {/* Tailwind Custom CSS */}
      <style>{`
        .btn:hover {
          background-color: #f6f6f6;
          transform: scale(1.1);
        }
      `}</style>
    </div>
  );
}